import json,html
from pathlib import Path
R=Path(__file__).resolve().parents[1]; C=json.loads((R/'content.json').read_text())
def e(s):return html.escape(str(s),quote=True)
def url(p,l):return ('fa' if p=='home' and l=='fa' else 'index' if p=='home' else p+('-fa' if l=='fa' else ''))+'.html'
def link(p,t,l,cls=''):return f'<a class="{cls}" href="{url(p,l)}">{e(t)}</a>'
def section(title,text='',body=''):return f'<section class="section wrap"><div class="section-head"><h2>{e(title)}</h2><p>{e(text)}</p></div>{body}</section>'
def rows(items):return '<div class="rows">'+''.join(f'<article class="row"><span class="number">{i+1:02}</span><h3>{e(x[0])}</h3><div><p>{e(x[1])}</p>'+ ('<ul>'+''.join('<li>'+e(y)+'</li>' for y in x[2])+'</ul>' if len(x)>2 else '')+'</div></article>' for i,x in enumerate(items))+'</div>'
def render(p,l):
 d=C[l]; fa=l=='fa'; T=lambda en,fa_:fa_ if fa else en
 cta=T('Book a free consultation','درخواست مشاوره رایگان')
 nav=''.join(link(k,d['pages'][k],l,'active' if p==k else '') for k in ['services','approach','pathways','about'])
 out=f'''<!doctype html><html lang="{l}" dir="{'rtl' if fa else 'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(d['pages'][p])} | Vellum House</title><meta name="description" content="{e(d['description'])}"><meta name="theme-color" content="#0c1c2d"><meta property="og:title" content="{e(d['pages'][p])} | Vellum House"><meta property="og:description" content="{e(d['description'])}"><meta property="og:type" content="website"><link rel="alternate" hreflang="en" href="{url(p,'en')}"><link rel="alternate" hreflang="fa" href="{url(p,'fa')}"><link rel="icon" href="assets/favicon.svg"><link rel="stylesheet" href="assets/style.css"><script defer src="assets/config.js"></script><script defer src="assets/main.js"></script></head><body><a class="skip" href="#main">{e(d['skip'])}</a><header><div class="wrap nav"><a class="brand" href="{url('home',l)}" aria-label="Vellum House"><img src="assets/logo-mark.svg" width="44" height="44" alt=""><span>VELLUM HOUSE<small>{e(d['tag'])}</small></span></a><button id="menu" aria-expanded="false" aria-controls="navigation">{e(d['menu'])} ☰</button><nav id="navigation" aria-label="{e(d['navLabel'])}">{nav}<a class="language" href="{url(p,'en' if fa else 'fa')}" lang="{'en' if fa else 'fa'}">{'English' if fa else 'فارسی'}</a>{link('contact',cta,l,'button small')}</nav></div></header><main id="main">'''
